	if scheme := c.request.Header.Get(HeaderXForwardedProto); isSchemeValid(scheme) {
		return scheme
	}
	if scheme := c.request.Header.Get(HeaderXForwardedProtocol); isSchemeValid(scheme) {
		return scheme
	}
	if ssl := c.request.Header.Get(HeaderXForwardedSsl); ssl == "on" {
		return "https"
	}
	if scheme := c.request.Header.Get(HeaderXUrlScheme); isSchemeValid(scheme) {
		return scheme
	}
	return "http"
}

// isSchemeValid reports whether the given header value is a valid HTTP scheme
// (`http` or `https`). Other values are considered invalid and are ignored.
func isSchemeValid(scheme string) bool {
	return scheme == "http" || scheme == "https"
}
