package echo

import (
	"fmt"
	"net/http"
	"strings"
	"testing"
)

type pseg struct {
	kind int // 0 static, 1 param, 2 any
	val  string
}

func parsePattern(p string) []pseg {
	parts := strings.Split(p[1:], "/")
	segs := []pseg{}
	for _, s := range parts {
		if s == "*" {
			segs = append(segs, pseg{2, s})
		} else if strings.HasPrefix(s, ":") {
			segs = append(segs, pseg{1, s[1:]})
		} else {
			segs = append(segs, pseg{0, s})
		}
	}
	return segs
}

func matchPattern(segs []pseg, parts []string) bool {
	i := 0
	for ; i < len(segs); i++ {
		if segs[i].kind == 2 {
			return i <= len(parts)-1
		}
		if i >= len(parts) {
			return false
		}
		if segs[i].kind == 0 {
			if segs[i].val != parts[i] {
				return false
			}
		} else if parts[i] == "" {
			return false
		}
	}
	return i == len(parts)
}

func better(a, b []pseg) bool {
	for i := 0; i < len(a) && i < len(b); i++ {
		if a[i].kind != b[i].kind {
			return a[i].kind < b[i].kind
		}
	}
	return len(a) > len(b)
}

func refMatch(patterns []string, path string) (string, bool) {
	parts := strings.Split(path[1:], "/")
	var best string
	found := false
	for _, p := range patterns {
		segs := parsePattern(p)
		if !matchPattern(segs, parts) {
			continue
		}
		if !found || better(segs, parsePattern(best)) {
			best = p
			found = true
		}
	}
	return best, found
}

