			return res
		}
		for _, c := range segsChoices {
			for _, sub := range gen(depth - 1) {
				var s string
				if sub == "/" {
					s = "/" + c
				} else {
					s = sub + "/" + c
				}
				res = append(res, s)
			}
		}
		return res
	}
