			continue
		}
		patterns = append(patterns, p)
	}
	paths := []string{"/", "/a", "/b", "/a/", "/a/a", "/a/b", "/a/a/", "/a/a/a", "/a/a/b", "/a/b/a", "/a/a/a/a", "/b/a/b/a"}

	// random subsets
