func TestZZGroupSamePath(t *testing.T) {
	e := New()
	var order []string
	mw := func(name string) MiddlewareFunc {
		return func(next HandlerFunc) HandlerFunc {
			return func(c Context) error {
				order = append(order, name)
				return next(c)
			}
		}
	}
	g1 := e.Group("/api", mw("g1"))
	g1.GET("/users", func(c Context) error { return c.String(200, "g1") })
	g2 := e.Group("/api", mw("g2"))
	g2.GET("/users", func(c Context) error { return c.String(200, "g2") })

	req := httptest.NewRequest(http.MethodGet, "/api/users", nil)
	rec := httptest.NewRecorder()
	e.ServeHTTP(rec, req)
	fmt.Println("resp:", rec.Body.String(), "order:", order)

	order = nil
	req = httptest.NewRequest(http.MethodGet, "/api/nope", nil)
	rec = httptest.NewRecorder()
	e.ServeHTTP(rec, req)
	fmt.Println("404 resp:", rec.Code, rec.Body.String(), "order:", order)
}
EOF
